CREATE POLICY "staff read product images" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'product-images' AND (has_role(auth.uid(),'admin'::app_role) OR has_role(auth.uid(),'staff'::app_role)));
CREATE POLICY "staff upload product images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'product-images' AND (has_role(auth.uid(),'admin'::app_role) OR has_role(auth.uid(),'staff'::app_role)));
CREATE POLICY "staff update product images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'product-images' AND (has_role(auth.uid(),'admin'::app_role) OR has_role(auth.uid(),'staff'::app_role)));
CREATE POLICY "staff delete product images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'product-images' AND (has_role(auth.uid(),'admin'::app_role) OR has_role(auth.uid(),'staff'::app_role)));